// Code generated by "go run ./cmd/gensdkjs" in the exe.dev repository. DO NOT EDIT.

import { ExeProtocolError, quote } from "./client.js";
import type { SSHOptions, SSHResult } from "./client.js";
import type { CallOptions } from "./commands.gen.js";
import { webCrypto } from "./token.js";

// Files on a VM, over vm.ssh(): /exec has no stdin, so data travels as
// base64 command-line arguments, in parts when it is large. The scripts are
// POSIX shell, run with sh, so they work whatever the VM user's login shell
// is. They match the Python SDK's (cmd/gensdkpy/templates/_wire.py).

/** What the file functions need of a VM. */
export interface FileVM {
  readonly name: string;
  ssh(command: string, options?: SSHOptions): Promise<SSHResult>;
}

export interface WriteFileOptions extends CallOptions {
  /** Permissions for the file, such as 0o755. */
  mode?: number;
}

export interface UploadOptions extends CallOptions {
  /**
   * Leave out files and directories whose names match any of these patterns
   * (*, ?, and [...] as in a shell), such as [".git", "node_modules", "*.pyc"].
   */
  exclude?: readonly string[];
}

/**
 * One of the SDK's own commands on the VM failed, such as a missing base64,
 * gzip, or tar, or a full disk. details() has the command's error output.
 */
export class CommandError extends Error {
  readonly #stderr: string;
  constructor(readonly operation: string, readonly exitCode: number, stderr: string) {
    super(`exedev: ${operation} failed on the VM (exit code ${exitCode})`);
    this.name = "CommandError";
    this.#stderr = stderr;
  }
  /** The command's error output; may contain secrets. */
  details(): { stderr: string } { return { stderr: this.#stderr }; }
}

/** A path on the VM is missing (ENOENT), or is a directory where a file is needed (EISDIR). */
export class VMFileError extends Error {
  constructor(readonly code: "ENOENT" | "EISDIR", readonly vm: string, readonly path: string) {
    super(`exedev: ${code === "ENOENT" ? "no such file or directory" : "is a directory"} on VM ${vm}: ${path}`);
    this.name = "VMFileError";
  }
}

const execLimit = 64 * 1024;
/** Base64 characters per part of a large file: a part's request must fit in execLimit. */
const partSize = 63 * 1024;
/** Requests in flight at once for one file. */
const parallel = 8;
const unlimited = Number.MAX_SAFE_INTEGER;
const missing = 2;
const isDirectory = 3;

// $1 path, $2 base64 data, or "" to read the parts in directory $5;
// $3 mode or ""; $4 "gz" if the data is gzipped.
const writeScript = `f=$1 data=$2 mode=$3 gz=$4 parts=$5
data() { if [ -n "$parts" ]; then cat "$parts"/*; else printf %s "$data"; fi; }
case $f in */*) mkdir -p "\${f%/*}" || exit;; esac
if [ -n "$gz" ]; then data | base64 -d | gzip -dc > "$f"; else data | base64 -d > "$f"; fi
c=$?
if [ -n "$parts" ]; then rm -rf "$parts"; fi
if [ $c = 0 ] && [ -n "$mode" ]; then chmod "$mode" "$f" || c=$?; fi
exit $c`;
// $1 directory, $2 part number, $3 base64 data.
const partScript = `mkdir -p "$1" && printf %s "$3" > "$1/$2"`;
const readScript = `if [ -d "$1" ]; then exit 3; fi
if [ ! -e "$1" ]; then exit 2; fi
exec cat "$1"`;
// Prints D and a gzipped tar of a directory's contents, or F and a file.
const downloadScript = `if [ -d "$1" ]; then printf D && exec tar -czf - -C "$1" .; fi
if [ ! -e "$1" ]; then exit 2; fi
printf F && exec cat "$1"`;
// $1 archive, $2 directory to extract it into.
const untarScript = `mkdir -p "$2" && tar -xzf "$1" -C "$2"; c=$?; rm -f "$1"; exit $c`;

/** A command line that runs script with sh, with args as $1, $2, .... */
function sh(script: string, ...args: string[]): string {
  return ["sh", "-c", script, "sh", ...args].map(quote).join(" ");
}

function fits(vm: string, command: string): boolean {
  return new TextEncoder().encode(`ssh ${quote(vm)} ${quote(command)}`).length <= execLimit;
}

/** A path on the VM, relative to the home directory unless absolute, that cannot be read as an option. */
function remotePath(value: unknown): string {
  if (typeof value !== "string" || !value || value.includes("\0")) throw new TypeError("exedev: a path on the VM must be a nonempty string");
  let path = value;
  // Not expanded by a shell: the home directory is where relative paths start.
  if (path === "~" || path.startsWith("~/")) path = "." + path.slice(1);
  return path.startsWith("-") ? "./" + path : path;
}

function fileMode(mode: unknown): string {
  if (mode === undefined) return "";
  if (!Number.isInteger(mode) || (mode as number) < 0 || (mode as number) > 0o7777) {
    throw new TypeError("exedev: mode must be an integer such as 0o644");
  }
  return (mode as number).toString(8);
}

async function randomHex(bytes: number): Promise<string> {
  return Array.from((await webCrypto()).getRandomValues(new Uint8Array(bytes)), (b) => b.toString(16).padStart(2, "0")).join("");
}

function encodeBase64(data: Uint8Array): string {
  const parts: string[] = [];
  for (let i = 0; i < data.length; i += 0xc000) {
    parts.push(btoa(String.fromCharCode(...data.subarray(i, i + 0xc000))));
  }
  return parts.join("");
}

async function transform(data: Uint8Array, stream: CompressionStream | DecompressionStream): Promise<Uint8Array> {
  return new Uint8Array(await new Response(new Blob([data as BlobPart]).stream().pipeThrough(stream)).arrayBuffer());
}

/** Data to send, and whether it is gzipped: a large file, if that makes it smaller. */
async function pack(data: string | Uint8Array): Promise<[Uint8Array, boolean]> {
  let raw: Uint8Array;
  if (typeof data === "string") raw = new TextEncoder().encode(data);
  else if (data instanceof Uint8Array) raw = data;
  else throw new TypeError("exedev: data must be a string or a Uint8Array");
  if (raw.length > partSize && typeof CompressionStream === "function") {
    const packed = await transform(raw, new CompressionStream("gzip"));
    if (packed.length < raw.length * 0.9) return [packed, true];
  }
  return [raw, false];
}

/** Run one of the SDK's scripts. An exit status other than 0 or those in ok throws CommandError. */
async function script(
  vm: FileVM, operation: string, command: string, signal?: AbortSignal,
  ok: readonly number[] = [], maxOutputBytes = 1 << 20,
): Promise<SSHResult> {
  const result = await vm.ssh(command, { signal, maxOutputBytes });
  if (result.exitCode !== 0 && !ok.includes(result.exitCode)) {
    throw new CommandError(operation, result.exitCode, result.stderr);
  }
  return result;
}

/** Run jobs, a few at a time. The first to fail stops the rest. */
async function inParallel(jobs: ((signal: AbortSignal) => Promise<unknown>)[], signal?: AbortSignal): Promise<void> {
  const controller = new AbortController();
  const abort = () => controller.abort(signal!.reason);
  signal?.addEventListener("abort", abort, { once: true });
  if (signal?.aborted) abort();
  let next = 0;
  let failure: { err: unknown } | undefined;
  const worker = async () => {
    while (!failure && next < jobs.length) {
      const job = jobs[next++];
      try {
        await job(controller.signal);
      } catch (err) {
        failure ??= { err };
        controller.abort(err);
      }
    }
  };
  try {
    await Promise.all(Array.from({ length: Math.min(parallel, jobs.length) }, worker));
  } finally {
    signal?.removeEventListener("abort", abort);
  }
  signal?.throwIfAborted();
  if (failure) throw failure.err;
}

export async function writeFile(
  vm: FileVM, path: string, data: string | Uint8Array, options: WriteFileOptions = {},
): Promise<void> {
  const { signal } = options;
  const remote = remotePath(path);
  const flags = [fileMode(options.mode)];
  const [packed, gz] = await pack(data);
  flags.push(gz ? "gz" : "");
  const encoded = encodeBase64(packed);
  const command = sh(writeScript, remote, encoded, ...flags, "");
  if (fits(vm.name, command)) {
    await script(vm, "writeFile", command, signal);
    return;
  }
  const parts = `/tmp/.exedev-upload-${await randomHex(8)}`;
  const jobs = [];
  for (let i = 0, start = 0; start < encoded.length; i++, start += partSize) {
    const part = sh(partScript, parts, String(i).padStart(6, "0"), encoded.slice(start, start + partSize));
    jobs.push((signal: AbortSignal) => script(vm, "writeFile", part, signal));
  }
  try {
    await inParallel(jobs, signal);
  } catch (err) {
    await vm.ssh(`rm -rf ${parts}`, { capture: false, signal: AbortSignal.timeout(30_000) }).catch(() => {});
    throw err;
  }
  await script(vm, "writeFile", sh(writeScript, remote, "", ...flags, parts), signal);
}

export async function readFile(vm: FileVM, path: string, options: CallOptions = {}): Promise<Uint8Array> {
  const result = await script(vm, "readFile", sh(readScript, remotePath(path)), options.signal, [missing, isDirectory], unlimited);
  fileError(vm, result.exitCode, path);
  return result.stdoutBytes;
}

function fileError(vm: FileVM, exitCode: number, path: string): void {
  if (exitCode === missing) throw new VMFileError("ENOENT", vm.name, path);
  if (exitCode === isDirectory) throw new VMFileError("EISDIR", vm.name, path);
}

export async function upload(vm: FileVM, local: string, remote: string, options: UploadOptions = {}): Promise<void> {
  const { fs, path } = await node();
  const destination = remotePath(remote);
  const exclude = options.exclude ?? [];
  if (typeof exclude === "string" || !Array.isArray(exclude)) throw new TypeError("exedev: exclude must be an array of patterns");
  const st = await fs.stat(local);
  if (st.isDirectory()) {
    const archive = await transform(await tarDirectory(fs, path, local, exclude.map(pattern)), new CompressionStream("gzip"));
    const temporary = `/tmp/.exedev-upload-${await randomHex(8)}.tgz`;
    await writeFile(vm, temporary, archive, { signal: options.signal });
    await script(vm, "upload", sh(untarScript, temporary, destination), options.signal);
  } else {
    await writeFile(vm, destination, await fs.readFile(local), { mode: st.mode & 0o7777, signal: options.signal });
  }
}

export async function download(vm: FileVM, remote: string, local: string, options: CallOptions = {}): Promise<void> {
  const result = await script(vm, "download", sh(downloadScript, remotePath(remote)), options.signal, [missing], unlimited);
  fileError(vm, result.exitCode, remote);
  const data = result.stdoutBytes;
  const { fs, path } = await node();
  if (data[0] === 0x46 /* F */) {
    await fs.writeFile(local, data.subarray(1));
  } else if (data[0] === 0x44 /* D */) {
    await untar(fs, path, await transform(data.subarray(1), new DecompressionStream("gzip")), local);
  } else {
    throw new ExeProtocolError("download");
  }
}

// Local files, for upload() and download(), which need Node.js (or a
// runtime with its node:fs, such as Bun or Deno). The package's types do not
// depend on @types/node, so these are the parts it uses.

interface Stats {
  isDirectory(): boolean;
  isFile(): boolean;
  isSymbolicLink(): boolean;
  mode: number;
  mtimeMs: number;
}
interface NodeFS {
  stat(path: string): Promise<Stats>;
  lstat(path: string): Promise<Stats>;
  readdir(path: string): Promise<string[]>;
  readFile(path: string): Promise<Uint8Array>;
  readlink(path: string): Promise<string>;
  realpath(path: string): Promise<string>;
  writeFile(path: string, data: Uint8Array, options?: { mode?: number; flag?: string }): Promise<void>;
  mkdir(path: string, options: { recursive: true }): Promise<unknown>;
  rm(path: string, options: { force: true }): Promise<void>;
  symlink(target: string, path: string): Promise<void>;
  copyFile(source: string, destination: string): Promise<void>;
}
interface NodePath {
  sep: string;
  join(...paths: string[]): string;
  resolve(...paths: string[]): string;
  dirname(path: string): string;
  posix: { normalize(path: string): string; join(...paths: string[]): string; dirname(path: string): string };
}

async function node(): Promise<{ fs: NodeFS; path: NodePath }> {
  // Variables, so that bundlers for browsers leave them alone.
  const fsModule = "node:fs/promises", pathModule = "node:path";
  try {
    const [fs, path] = await Promise.all([
      import(/* webpackIgnore: true */ /* @vite-ignore */ fsModule),
      import(/* webpackIgnore: true */ /* @vite-ignore */ pathModule),
    ]);
    return { fs, path };
  } catch (err) {
    throw new Error("exedev: upload and download need node:fs (Node.js, Bun, or Deno); use writeFile and readFile", { cause: err });
  }
}

/** A shell-style pattern as a regular expression for a whole name. */
function pattern(glob: string): RegExp {
  if (typeof glob !== "string") throw new TypeError("exedev: exclude must be an array of patterns");
  let re = "";
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i];
    if (c === "*") re += ".*";
    else if (c === "?") re += ".";
    else if (c === "[" && glob.indexOf("]", i + 2) > 0) {
      const end = glob.indexOf("]", i + 2);
      let set = glob.slice(i + 1, end);
      if (set.startsWith("!")) set = "^" + set.slice(1);
      re += `[${set.replace(/[\\\]]/g, "\\$&")}]`;
      i = end;
    } else re += c.replace(/[.*+?^${}()|[\]\\/]/g, "\\$&");
  }
  return new RegExp(`^${re}$`, "s");
}

// A tar of a directory's contents, in the POSIX (pax) format: what
// upload() sends to the VM's tar, and download() reads from it (GNU tar's
// format, by default). Regular files, directories, and symbolic links only.

const block = 512;

function tarHeader(name: string, type: string, size: number, mode: number, mtime: number, link = ""): Uint8Array[] {
  const enc = new TextEncoder();
  const out: Uint8Array[] = [];
  const nameBytes = enc.encode(name), linkBytes = enc.encode(link);
  if (nameBytes.length > 100 || linkBytes.length > 100) {
    // Long names go in a pax extended header before the entry.
    let records = "";
    for (const [key, value] of [["path", name], ["linkpath", link]]) {
      if (key === "linkpath" && !link) continue;
      const body = ` ${key}=${value}\n`;
      // A record's length counts its own digits.
      const n = enc.encode(body).length;
      let length = n + 1;
      while (String(length).length + n !== length) length = String(length).length + n;
      records += `${length}${body}`;
    }
    const data = enc.encode(records);
    out.push(...tarHeader("././@PaxHeader", "x", data.length, 0o644, mtime), ...padded(data));
  }
  const h = new Uint8Array(block);
  const put = (offset: number, length: number, value: Uint8Array) => h.set(value.subarray(0, length), offset);
  const octal = (offset: number, length: number, value: number) =>
    put(offset, length, enc.encode(value.toString(8).padStart(length - 1, "0") + "\0"));
  if (size > 0o77777777777) throw new Error(`exedev: ${name} is too large to upload`);
  put(0, 100, nameBytes);
  octal(100, 8, mode);
  octal(108, 8, 0);
  octal(116, 8, 0);
  octal(124, 12, size);
  octal(136, 12, Math.max(0, Math.min(mtime, 0o77777777777)));
  h.fill(0x20, 148, 156);
  h[156] = type.charCodeAt(0);
  put(157, 100, linkBytes);
  put(257, 8, enc.encode("ustar\x0000"));
  octal(148, 7, h.reduce((sum, b) => sum + b, 0));
  out.push(h);
  return out;
}

function padded(data: Uint8Array): Uint8Array[] {
  const pad = (block - data.length % block) % block;
  return pad ? [data, new Uint8Array(pad)] : [data];
}

async function tarDirectory(fs: NodeFS, path: NodePath, root: string, exclude: RegExp[]): Promise<Uint8Array> {
  const chunks: Uint8Array[] = [];
  const walk = async (dir: string, prefix: string) => {
    for (const name of (await fs.readdir(dir)).sort()) {
      if (exclude.some((re) => re.test(name))) continue;
      const local = path.join(dir, name), member = prefix + name;
      const st = await fs.lstat(local);
      const mtime = Math.floor(st.mtimeMs / 1000), mode = st.mode & 0o7777;
      if (st.isSymbolicLink()) {
        chunks.push(...tarHeader(member, "2", 0, 0o777, mtime, await fs.readlink(local)));
      } else if (st.isDirectory()) {
        chunks.push(...tarHeader(member + "/", "5", 0, mode, mtime));
        await walk(local, member + "/");
      } else if (st.isFile()) {
        const data = await fs.readFile(local);
        chunks.push(...tarHeader(member, "0", data.length, mode, mtime), ...padded(data));
      }
    }
  };
  await walk(root, "");
  chunks.push(new Uint8Array(2 * block));
  const out = new Uint8Array(chunks.reduce((n, c) => n + c.length, 0));
  let at = 0;
  for (const c of chunks) { out.set(c, at); at += c.length; }
  return out;
}

/**
 * Extract a tar from the VM into root. Members that would land outside root,
 * or are not regular files, directories, or links within it, are refused.
 */
async function untar(fs: NodeFS, path: NodePath, data: Uint8Array, root: string): Promise<void> {
  const dec = new TextDecoder();
  const refuse = (why: string) => new Error(`exedev: download: ${why}`);
  const field = (h: Uint8Array, offset: number, length: number) => {
    const s = h.subarray(offset, offset + length);
    const end = s.indexOf(0);
    return dec.decode(end < 0 ? s : s.subarray(0, end));
  };
  const number = (h: Uint8Array, offset: number, length: number) => {
    if (h[offset] & 0x80) {
      // GNU base-256, for values too large for octal.
      let n = h[offset] & 0x7f;
      for (let i = 1; i < length; i++) n = n * 256 + h[offset + i];
      return n;
    }
    const s = field(h, offset, length).trim();
    if (!/^[0-7]*$/.test(s)) throw new ExeProtocolError("download");
    return s ? parseInt(s, 8) : 0;
  };
  await fs.mkdir(root, { recursive: true });
  const top = await fs.realpath(root);
  const inside = (p: string) => p === top || p.startsWith(top.endsWith(path.sep) ? top : top + path.sep);
  // The member's path within root, or undefined for root itself.
  const member = (name: string): string | undefined => {
    if (name.startsWith("/")) throw refuse(`absolute path ${JSON.stringify(name)}`);
    const clean = path.posix.normalize(name).replace(/\/+$/, "");
    if (clean === "." || clean === "") return undefined;
    if (clean === ".." || clean.startsWith("../")) throw refuse(`path outside the directory ${JSON.stringify(name)}`);
    return clean;
  };
  // Where to put a member: its parent made, and inside root once links are followed.
  const place = async (name: string) => {
    const target = path.join(top, ...name.split("/"));
    await fs.mkdir(path.dirname(target), { recursive: true });
    if (!inside(await fs.realpath(path.dirname(target)))) throw refuse(`path outside the directory ${JSON.stringify(name)}`);
    return target;
  };
  const files = new Set<string>();
  let longName: string | undefined, longLink: string | undefined;
  let pax: Record<string, string> = {};
  for (let at = 0; at + block <= data.length;) {
    const h = data.subarray(at, at + block);
    if (h.every((b) => b === 0)) break;
    let sum = 0;
    for (let i = 0; i < block; i++) sum += i >= 148 && i < 156 ? 0x20 : h[i];
    if (sum !== number(h, 148, 8)) throw new ExeProtocolError("download");
    const type = String.fromCharCode(h[156] || 0x30);
    const size = pax.size !== undefined ? Number(pax.size) : number(h, 124, 12);
    const body = data.subarray(at + block, at + block + size);
    if (body.length !== size) throw new ExeProtocolError("download");
    at += block + Math.ceil(size / block) * block;
    if (type === "L" || type === "K") {
      const text = dec.decode(body).replace(/\0.*$/s, "");
      if (type === "L") longName = text; else longLink = text;
      continue;
    }
    if (type === "x" || type === "g") {
      if (type === "x") {
        pax = {};
        for (let text = dec.decode(body); text;) {
          const space = text.indexOf(" "), length = parseInt(text, 10);
          if (!(length > 0) || space < 0) throw new ExeProtocolError("download");
          const record = text.slice(space + 1, length - 1);
          const eq = record.indexOf("=");
          pax[record.slice(0, eq)] = record.slice(eq + 1);
          text = text.slice(length);
        }
      }
      continue;
    }
    const prefix = field(h, 345, 155);
    const name = pax.path ?? longName ?? (prefix ? `${prefix}/` : "") + field(h, 0, 100);
    const link = pax.linkpath ?? longLink ?? field(h, 157, 100);
    const mode = number(h, 100, 8);
    pax = {};
    longName = longLink = undefined;
    const relative = member(name);
    if (type === "5") {
      if (relative !== undefined) await fs.mkdir(await place(relative), { recursive: true });
      continue;
    }
    if (relative === undefined) throw refuse(`${JSON.stringify(name)} is not a directory`);
    const target = await place(relative);
    await fs.rm(target, { force: true });
    if (type === "0" || type === "7") {
      // As Python's "data" filter: no setuid, setgid, sticky, or group and other write bits.
      await fs.writeFile(target, body, { mode: (mode & 0o755) | 0o600, flag: "wx" });
      files.add(relative);
    } else if (type === "2") {
      if (!link || link.startsWith("/")) throw refuse(`link ${JSON.stringify(name)} points outside the directory`);
      const resolved = path.posix.normalize(path.posix.join(path.posix.dirname(relative), link));
      if (resolved === ".." || resolved.startsWith("../")) throw refuse(`link ${JSON.stringify(name)} points outside the directory`);
      await fs.symlink(link, target);
    } else if (type === "1") {
      const source = member(link);
      if (source === undefined || !files.has(source)) throw refuse(`hard link ${JSON.stringify(name)} to ${JSON.stringify(link)}`);
      await fs.copyFile(await place(source), target);
      files.add(relative);
    } else {
      throw refuse(`${JSON.stringify(name)} is not a regular file, directory, or link`);
    }
  }
}
